import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    process = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    ps_proc = psutil.Process(process.pid)

    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()

    try:
        while process.poll() is None:
            if time.time() - start_time > timeout:
                process.terminate()
                break

            try:
                cpu_usage += ps_proc.cpu_percent(interval=0.1)
                mem_info = ps_proc.memory_info()
                mem_usage += mem_info.rss
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                break

            time.sleep(0.1)
    finally:
        if process.poll() is None:
            process.kill()

    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

import subprocess
import logging
import os

def task_func(filepath):
    if not os.path.exists(filepath):
        raise FileNotFoundError(f"The file {filepath} does not exist.")

    output_filename = os.path.splitext(filepath)[0]

    try:
        subprocess.check_call(['g++', filepath, '-o', output_filename])
        logging.info(f"Compilation of {filepath} was successful.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Compilation of {filepath} failed with error: {e}")
        raise e
    except FileNotFoundError as e:
        logging.error(f"Compiler not found: {e}")
        raise e

import subprocess
import platform
import time

def task_func(url):
    system = platform.system()
    if system == 'Windows':
        process = subprocess.Popen(['start', url], shell=True)
    elif system == 'Darwin':
        process = subprocess.Popen(['open', url])
    else:
        process = subprocess.Popen(['xdg-open', url])

    time.sleep(1)
    return process.poll()
